  async onWoundGear(k, A) { const C = this.c; if (!this.gearHas(k, 'woundArmorMove')) return; if (C.isSm) { const SD = Object.keys(C.sm.nodes); const v = await C.ask({ type: 'pick', knight: k.id, text: `${k.name}: Wound — Ward Node에 Armor 토큰 1개 놓기? (${C.smNodeText()})`, options: [...SD.map(s => ({ label: `${s} (${C.sm.nodes[s]})`, value: s })), { label: '놓지 않음', value: 'skip' }] }); if (SD.includes(v)) { C.sm.nodes[v] += 1; this.say(`${k.name}: Ward Node ${v}에 Armor 토큰 +1 (${C.smNodeText()})`, 'tech'); } } else if (C.monster.isMob) { const src = C.monster.mobs.filter(m => m.armor > 0); if (!src.length || C.monster.mobs.length < 2) return; const a = await C.ask({ type: 'pick', knight: k.id, text: `${k.name}: Wound — Armor 토큰 1개를 옮길 Mob (어디서)`, options: [...src.map(m => ({ label: `#${m.n} (Armor ${m.armor})`, value: m.n })), { label: '옮기지 않음', value: 'skip' }] }); const from = src.find(m => m.n === a); if (!from) return; const dst = C.monster.mobs.filter(m => m !== from); const b = await C.ask({ type: 'pick', knight: k.id, text: '어디로', options: dst.map(m => ({ label: `#${m.n} (Armor ${m.armor})`, value: m.n })) }); const to = dst.find(m => m.n === b) || dst[0]; from.armor--; to.armor++; this.say(`${k.name}: Armor 토큰 #${from.n} → #${to.n}`, 'tech'); } }
