  async startMonsterRoundGear() { const C = this.c; if (!C.monster.isMob) return; for (const k of C.alive()) { const c = this.gearAbilities(k, ['moveActTokens'])[0]; if (!c) continue; const mobs = C.monster.mobs; const toks = mobs.flatMap(m => m.tokens); if (!toks.length || mobs.length < 2) continue; if (!await C.yesNo(`${k.name}: ${c.g.name} — Heat 1로 모든 Activation 토큰을 원하는 Mob으로 옮기기?`, false)) continue; this.gearPay(k, c.g, c.o); for (const m of mobs) m.tokens = []; for (const tk of toks) { const v = await C.ask({ type: 'pick', knight: k.id, text: `Activation 토큰(${tk.type})을 놓을 Mob`, options: mobs.map(m => ({ label: `#${m.n} ${m.revealed ? m.card.name : 'BP' + m.card.level}${m.tokens.length ? ` (토큰 ${m.tokens.length})` : ''}`, value: m.n })) }); (mobs.find(m => m.n === v) || mobs[0]).tokens.push(tk); } this.say(`${k.name}: ${c.g.name} — Activation 토큰 재배치: ${mobs.filter(m => m.tokens.length).map(m => `#${m.n}×${m.tokens.length}`).join(', ')}`, 'tech'); } }
  // ---------- Saints (rulebook p.68–69) ----------
